/**
 * Validates the current daily AI request limit based on Firebase data.
 *
 * Purpose:
 * - Reads the persisted email request limit configuration
 * - Resets the daily counter automatically when the date changes
 * - Exposes whether the AI daily limit has already been reached
 *
 * Output:
 * - firebaseData: complete Firebase snapshot
 * - currentDate: normalized current date for limit tracking
 * - requestCount: current number of AI-created requests today
 * - dailyLimit: maximum allowed AI-created requests per day
 * - limitReached: true when no more AI tickets may be generated today
 */

const firebaseData = $json;
const today = new Date().toISOString().slice(0, 10);
const limitData = firebaseData.emailRequestLimit || {};
let currentDate = limitData.currentDate || today;
let requestCount = Number(limitData.requestCount || 0);
const dailyLimit = Number(limitData.dailyLimit || 10);

if (currentDate !== today) {
  currentDate = today;
  requestCount = 0;
}

return [
  {
    json: {
      firebaseData,
      currentDate,
      requestCount,
      dailyLimit,
      limitReached: requestCount >= dailyLimit
    }
  }
];

/**
 * Builds the final Firebase ticket payload for an AI-generated request.
 *
 * Purpose:
 * - Creates the next task id from taskMeta.nextTaskNumber
 * - Extracts sender name and sender email from the incoming mail
 * - Maps AI output to the Join task structure
 * - Applies default metadata for externally created email tickets
 *
 * Output:
 * - nextTaskId: generated Firebase task key
 * - nextTaskNumber: current numeric task counter
 * - ticket: complete Join-compatible task object
 * - limit context values for later workflow steps
 */

const source = $("Check Daily Limit").item.json;
const email = $("Email Trigger (IMAP)").item.json;
const ai = $json.output;
const firebaseData = source.firebaseData;
const nextTaskNumber = Number(firebaseData.taskMeta?.nextTaskNumber || 1);
const nextTaskId = `task-${String(nextTaskNumber).padStart(3, "0")}`;
const today = new Date();
const formattedToday = today.toLocaleDateString("de-DE");
const fromRaw = email.from || "";
const emailMatch = fromRaw.match(/<([^>]+)>/);
const creatorEmailRaw = emailMatch ? emailMatch[1].trim() : fromRaw.trim();

function buildCreatorNameFromEmail(emailAddress) {
  const localPart = String(emailAddress || "")
    .split("@")[0]
    .replace(/[0-9]/g, " ")
    .replace(/[._-]+/g, " ")
    .replace(/[^a-zA-ZäöüÄÖÜß\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!localPart) return "External Request";

  return localPart
    .split(" ")
    .filter(Boolean)
    .map((namePart) => {
      const lowerNamePart = namePart.toLowerCase();
      return lowerNamePart.charAt(0).toUpperCase() + lowerNamePart.slice(1);
    })
    .join(" ");
}

const creatorName = buildCreatorNameFromEmail(creatorEmailRaw);
function normalizeDeadline(deadlineValue) {
  const value = String(deadlineValue || "").trim();

  if (!value) return "";

  const germanDateMatch = value.match(/\b(\d{1,2})[.](\d{1,2})[.](\d{4})\b/);
  if (germanDateMatch) {
    const day = germanDateMatch[1].padStart(2, "0");
    const month = germanDateMatch[2].padStart(2, "0");
    const year = germanDateMatch[3];
    return `${day}.${month}.${year}`;
  }

  const isoDateMatch = value.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);
  if (isoDateMatch) {
    const year = isoDateMatch[1];
    const month = isoDateMatch[2].padStart(2, "0");
    const day = isoDateMatch[3].padStart(2, "0");
    return `${day}.${month}.${year}`;
  }

  return value;
}

function extractDeadlineFromEmailBody(emailBody) {
  const body = String(emailBody || "");
  const preferredDeadlineMatch = body.match(
    /Preferred deadline:\s*([^\n\r]+)/i,
  );

  if (!preferredDeadlineMatch) return "";

  return normalizeDeadline(preferredDeadlineMatch[1]);
}

const deadlineFromEmailBody = extractDeadlineFromEmailBody(email.textPlain);
const deadlineFromAi = normalizeDeadline(ai.deadline);
const finalDeadline = deadlineFromEmailBody || deadlineFromAi;

function cleanSubtaskTitle(subtaskValue) {
  return String(subtaskValue || "")
    .replace(/^subtasks?:\s*/i, "")
    .replace(/^[-*•]\s*/, "")
    .replace(/\bthis ticket was ai[-\s]?generated\b/gi, "")
    .replace(/\bai[-\s]?generated\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function buildSubtasks(rawSubtasks) {
  const rawList = Array.isArray(rawSubtasks)
    ? rawSubtasks
    : String(rawSubtasks || "")
        .split(/\n|,|;/)
        .map((value) => value.trim());

  const totalSubtasks = rawList
    .map(cleanSubtaskTitle)
    .filter(Boolean)
    .slice(0, 10);

  const checkedSubtasks = totalSubtasks.map(() => false);

  return { totalSubtasks, checkedSubtasks };
}

function cleanAiText(textValue, fallbackValue) {
  const cleanedText = String(textValue || fallbackValue || "")
    .replace(/\bthis ticket was ai[-\s]?generated\b/gi, "")
    .replace(/\bai[-\s]?generated\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();

  return cleanedText;
}

const { totalSubtasks, checkedSubtasks } = buildSubtasks(ai.subtasks);
const finalDescription = cleanAiText(
  ai.description,
  "Request was submitted by email."
);
const finalTitle = cleanAiText(ai.title, "New Request");

return [
  {
    json: {
      firebaseData,
      currentDate: source.currentDate,
      requestCount: source.requestCount,
      dailyLimit: source.dailyLimit,
      nextTaskNumber,
      nextTaskId,
      ticket: {
        assignedUsers: [],
        boardID: firebaseData.issueCollector.defaults.boardID,
        checkedSubtasks,
        columnID: firebaseData.issueCollector.defaults.columnID,
        createdAt: formattedToday,
        creatorEmail: creatorEmailRaw,
        creatorName,
        creatorSource: firebaseData.issueCollector.defaults.creatorSource,
        creatorType: firebaseData.issueCollector.defaults.creatorType,
        deadline: finalDeadline,
        description: finalDescription,
        isAIGenerated: firebaseData.issueCollector.defaults.isAIGenerated,
        priority: ai.priority || "medium",
        subtasksCompleted: 0,
        title: finalTitle,
        totalSubtasks,
        type: ai.type || "User Story",
        updatedAt: formattedToday,
      },
    },
  },
];

/**
 * Increments the persisted daily AI request counter after
 * a new AI-generated ticket has been created successfully.
 *
 * Purpose:
 * - Keeps the daily limit state in sync with successful AI ticket creation
 * - Prevents additional AI-generated tickets once the configured limit is reached
 *
 * Output:
 * - currentDate: active tracking date
 * - requestCount: incremented request count
 * - dailyLimit: unchanged configured maximum
 */

const source = $('Build AI Ticket Data').item.json;

return [
  {
    json: {
      dailyLimit: source.dailyLimit,
      currentDate: source.currentDate,
      requestCount: Number(source.requestCount) + 1
    }
  }
];

/**
 * Prepares the updated taskMeta payload for Firebase.
 *
 * Purpose:
 * - Increases the global nextTaskNumber after a ticket was created
 * - Ensures the following task receives a unique sequential task id
 *
 * Output:
 * - nextTaskNumber: incremented counter for the next ticket creation
 */

const source = $('Build AI Ticket Data').item.json;

return [
  {
    json: {
      nextTaskNumber: Number(source.nextTaskNumber) + 1
    }
  }
];

/**
 * Creates the confirmation email content for a successfully
 * AI-generated Join ticket.
 *
 * Purpose:
 * - Sends a stakeholder-facing confirmation after ticket creation
 * - Includes the generated title, category and priority
 * - Uses the original sender as recipient
 *
 * Output:
 * - toEmail: extracted sender email
 * - subject: confirmation subject line
 * - text: plain text confirmation message
 */

const email = $("Email Trigger (IMAP)").item.json;
const ticketData = $("Build AI Ticket Data").item.json;
const fromRaw = email.from || "";
const emailMatch = fromRaw.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1].trim() : fromRaw.trim();
const senderNameRaw = fromRaw
  .replace(/<[^>]+>/, "")
  .replace(/["']/g, "")
  .trim();
const senderName = senderNameRaw || "there";

return [
  {
    json: {
      toEmail: senderEmail,
      subject: "Your request was created as an AI ticket",
      text: `Hello ${senderName},

thank you for your message.

Your request was successfully received and created as a task in the Join board using AI.

Ticket title: ${ticketData.ticket.title}
Category: ${ticketData.ticket.type}
Priority: ${ticketData.ticket.priority}

Best regards
Join Team`,
    },
  },
];

/**
 * Creates the stakeholder reply for cases where the
 * daily AI generation limit has already been reached.
 *
 * Purpose:
 * - Informs the sender that no additional AI ticket can be created today
 * - Confirms that the request was still received for manual handling
 *
 * Output:
 * - toEmail: extracted sender email
 * - subject: reply subject line
 * - text: plain text limit notification
 */

const email = $("Email Trigger (IMAP)").item.json;
const fromRaw = email.from || "";
const emailMatch = fromRaw.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1].trim() : fromRaw.trim();
const senderNameRaw = fromRaw
  .replace(/<[^>]+>/, "")
  .replace(/["']/g, "")
  .trim();
const senderName = senderNameRaw || "there";

return [
  {
    json: {
      toEmail: senderEmail,
      subject: "Your request has been received",
      text: `Hello ${senderName},

thank you for your message.

The daily limit for AI-generated tickets has already been reached today.
Your request has still been received and will be handled manually as a task.

Best regards
Join Team`,
    },
  },
];

/**
 * Creates the fallback reply for automatic processing failures.
 *
 * Purpose:
 * - Informs the sender that the message was received successfully
 * - Explains that automatic processing failed
 * - Signals that the team will review the request manually
 *
 * Output:
 * - toEmail: extracted sender email
 * - subject: reply subject line
 * - text: plain text manual follow-up notification
 */

const email = $('Email Trigger (IMAP)').item.json;
const fromRaw = email.from || '';
const emailMatch = fromRaw.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1].trim() : fromRaw.trim();
const senderNameRaw = fromRaw.replace(/<[^>]+>/, '').replace(/["']/g, '').trim();
const senderName = senderNameRaw || 'there';

return [
  {
    json: {
      toEmail: senderEmail,
      subject: 'Your request has been received',
      text:
`Hello ${senderName},

thank you for your message.

We have received your request.
A problem occurred during automatic processing.
The team has been informed and will review your request manually.

Best regards
Join Team`
    }
  }
];
